import time
import threading
from collections import OrderedDict
from functools import wraps
from typing import Any, Callable, Hashable, TypeVar, overload

T = TypeVar("T")
K = TypeVar("K", bound=Hashable)

class LRUCache:
    def __init__(self, maxsize: int = 128, ttl: float = 60.0) -> None:
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")
        self.maxsize = maxsize
        self.ttl = ttl
        self._data: "OrderedDict[K, tuple[Any, float]]" = OrderedDict()
        self._lock = threading.RLock()

    def _now(self) -> float:
        return time.monotonic()

    def _expired(self, timestamp: float) -> bool:
        return (self._now() - timestamp) >= self.ttl

    def get(self, key: K) -> Any | None:
        with self._lock:
            item = self._data.get(key)
            if item is None:
                return None
            value, timestamp = item
            if self._expired(timestamp):
                self._data.pop(key, None)
                return None
            self._data.move_to_end(key)
            return value

    def set(self, key: K, value: Any) -> None:
        with self._lock:
            self._data[key] = (value, self._now())
            self._data.move_to_end(key)
            while len(self._data) > self.maxsize:
                self._data.popitem(last=False)

    def clear(self) -> None:
        with self._lock:
            self._data.clear()

    def __len__(self) -> int:
        with self._lock:
            self._purge_expired()
            return len(self._data)

    def _purge_expired(self) -> None:
        expired = [k for k, (_, ts) in self._data.items() if self._expired(ts)]
        for k in expired:
            self._data.pop(k, None)

def lru_cache(maxsize: int = 128, ttl: float = 60.0) -> Callable[[Callable[..., T]], Callable[..., T]]:
    def decorator(func: Callable[..., T]) -> Callable[..., T]:
        cache = LRUCache(maxsize=maxsize, ttl=ttl)

        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> T:
            key = (args, tuple(sorted(kwargs.items())))
            cached = cache.get(key)
            if cached is not None:
                return cached
            result = func(*args, **kwargs)
            cache.set(key, result)
            return result

        wrapper.cache = cache  # type: ignore[attr-defined]
        return wrapper

    return decorator

@overload
def cached(func: Callable[..., T]) -> Callable[..., T]: ...
@overload
def cached(maxsize: int = 128, ttl: float = 60.0) -> Callable[[Callable[..., T]], Callable[..., T]]: ...

def cached(func: Callable[..., T] | None = None, maxsize: int = 128, ttl: float = 60.0) -> Any:
    if func is not None:
        return lru_cache(maxsize=maxsize, ttl=ttl)(func)
    return lru_cache(maxsize=maxsize, ttl=ttl)

interface User {
  id: string;
  orgId: string;
  org?: unknown;
}

interface Org {
  id: string;
  [key: string]: unknown;
}

async function loadUser(id: string): Promise<User> {
  const res = await fetch(`/api/users/${encodeURIComponent(id)}`);
  if (!res.ok) {
    throw new Error(`Bad status ${res.status}`);
  }

  const user = (await res.json()) as User;

  const orgRes = await fetch(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  if (!orgRes.ok) {
    throw new Error(`Bad status ${orgRes.status}`);
  }

  user.org = (await orgRes.json()) as Org;
  return user;
}

async function loadUsers(ids: string[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

